package forge

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/Swarm-Code/mono/swarm-sdk/internal/tools"
)

// SnapshotContext records the conversational context that existed when a
// snapshot was taken.  It is written alongside every .bak file as a
// companion <filename>-<ts>.ctx.json so that FSUndo can explain *why*
// a file was changed, not just *what* changed.
type SnapshotContext struct {
	// ConversationID is the conversation that triggered the tool call.
	ConversationID string `json:"conversation_id,omitempty"`
	// AgentID is the agent definition ID that executed the tool.
	AgentID string `json:"agent_id,omitempty"`
	// UserMessage is the user's original request that led to this edit.
	// Truncated to 300 characters to keep the file compact.
	UserMessage string `json:"user_message,omitempty"`
	// ToolName is the tool that made the change ("Edit" or "Write").
	ToolName string `json:"tool_name"`
	// FilePath is the absolute path of the file that was modified.
	FilePath string `json:"file_path"`
	// Timestamp is when the snapshot was taken (RFC3339Nano).
	Timestamp string `json:"timestamp"`
	// NewFile is true when the snapshot was taken for a newly created file
	// (not a modification).  When FSUndo sees NewFile=true it deletes the
	// file rather than restoring contents, since there is no prior state.
	NewFile bool `json:"new_file,omitempty"`
}

// snapshotContextPath returns the companion .ctx.json path for a .bak file.
// e.g. "/ws/.swarm/snapshots/tools.go-1234.bak" →
//
//	"/ws/.swarm/snapshots/tools.go-1234.ctx.json"
func snapshotContextPath(bakPath string) string {
	return strings.TrimSuffix(bakPath, ".bak") + ".ctx.json"
}

// ensureSnapshotDir creates the snapshot directory and drops a .gitignore that
// ignores everything inside it. Without this, every file the agent edits leaves
// *.bak and *.ctx.json checkpoint artifacts that show up as untracked files in
// the user's `git status` (and the desktop/mobile git screen) — polluting the
// working tree with agent scratch. The `*` pattern also ignores the .gitignore
// itself, so the snapshots dir becomes entirely invisible to git. Idempotent;
// writing the .gitignore is best-effort and never blocks taking the snapshot.
func ensureSnapshotDir(dir string) error {
	if err := os.MkdirAll(dir, 0700); err != nil {
		return err
	}
	// Snapshots may contain secrets from 0600 source files. Tighten existing
	// directories too; MkdirAll does not update permissions on an old 0755 dir.
	if err := os.Chmod(dir, 0700); err != nil {
		return err
	}
	gi := filepath.Join(dir, ".gitignore")
	if _, err := os.Stat(gi); os.IsNotExist(err) {
		_ = os.WriteFile(gi, []byte("# Auto-generated by swarm: agent file snapshots — not for version control.\n*\n"), 0644)
	}
	return nil
}

// writeSnapshotContext writes a SnapshotContext alongside bakPath.
// Errors are silently discarded — a missing context file must never prevent
// a snapshot from being taken.
func writeSnapshotContext(bakPath string, ctx context.Context, toolName, absFilePath string) {
	sc := SnapshotContext{
		ConversationID: tools.OwnerConversationID(ctx),
		AgentID:        tools.OwnerAgentID(ctx),
		ToolName:       toolName,
		FilePath:       absFilePath,
		Timestamp:      time.Now().UTC().Format(time.RFC3339Nano),
	}

	// Truncate user message to keep the file small.
	msg := tools.UserMessageFromContext(ctx)
	if len(msg) > 300 {
		msg = msg[:297] + "..."
	}
	sc.UserMessage = msg

	writeSnapshotContextRaw(bakPath, sc)
}

// writeNewFileSnapshotContext writes a SnapshotContext with NewFile=true alongside
// bakPath.  Used when FSWrite creates a brand-new file so that FSUndo knows to
// delete the file rather than attempt to restore non-existent prior content.
func writeNewFileSnapshotContext(bakPath string, ctx context.Context, toolName, absFilePath string) {
	sc := SnapshotContext{
		ConversationID: tools.OwnerConversationID(ctx),
		AgentID:        tools.OwnerAgentID(ctx),
		ToolName:       toolName,
		FilePath:       absFilePath,
		Timestamp:      time.Now().UTC().Format(time.RFC3339Nano),
		NewFile:        true,
	}

	msg := tools.UserMessageFromContext(ctx)
	if len(msg) > 300 {
		msg = msg[:297] + "..."
	}
	sc.UserMessage = msg

	writeSnapshotContextRaw(bakPath, sc)
}

// writeSnapshotContextRaw marshals sc and writes it to the companion .ctx.json.
// Errors are silently discarded.
func writeSnapshotContextRaw(bakPath string, sc SnapshotContext) {
	data, err := json.MarshalIndent(sc, "", "  ")
	if err != nil {
		return
	}
	ctxPath := snapshotContextPath(bakPath)
	_ = os.WriteFile(ctxPath, data, 0644)
}

// readSnapshotContext reads the companion .ctx.json for a .bak file.
// Returns nil (no error) when the file does not exist.
func readSnapshotContext(bakPath string) (*SnapshotContext, error) {
	ctxPath := snapshotContextPath(bakPath)
	data, err := os.ReadFile(ctxPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("read snapshot context: %w", err)
	}
	var sc SnapshotContext
	if err := json.Unmarshal(data, &sc); err != nil {
		return nil, fmt.Errorf("parse snapshot context: %w", err)
	}
	return &sc, nil
}

// isNewFileSnapshot returns true when the snapshot was taken for a newly created
// file, meaning FSUndo should delete it rather than restore prior content.
func isNewFileSnapshot(bakPath string) bool {
	sc, err := readSnapshotContext(bakPath)
	return err == nil && sc != nil && sc.NewFile
}

// formatUndoMessage builds a human-readable result string for FSUndo that
// includes context from the companion .ctx.json when available.
func formatUndoMessage(absPath, snapName, snapshotDir string) string {
	bakPath := filepath.Join(snapshotDir, snapName)
	sc, _ := readSnapshotContext(bakPath)

	base := fmt.Sprintf("Successfully reverted %s", absPath)

	if sc == nil {
		return base
	}

	if sc.NewFile {
		base = fmt.Sprintf("Successfully deleted %s (was a newly created file — no prior state to restore)", absPath)
	}

	var parts []string
	if sc.ToolName != "" {
		parts = append(parts, fmt.Sprintf("tool: %s", sc.ToolName))
	}
	if sc.ConversationID != "" {
		parts = append(parts, fmt.Sprintf("conversation: %s", sc.ConversationID))
	}
	if sc.UserMessage != "" {
		parts = append(parts, fmt.Sprintf("because: %q", sc.UserMessage))
	}
	if sc.Timestamp != "" {
		parts = append(parts, fmt.Sprintf("at: %s", sc.Timestamp))
	}

	if len(parts) == 0 {
		return base
	}
	return base + "\n" + strings.Join(parts, " | ")
}
